import{_ as d,o as e,c as a,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/One-Sample-Mode.md","filePath":"manual-zh/One-Sample-Mode.md","lastUpdated":1785684581000}'),o={name:"manual-zh/One-Sample-Mode.md"};function n(r,t,i,p,l,h){return e(),a("div",null,[...t[0]||(t[0]=[s('<h4 id="_15-13-1-单样本模式" tabindex="-1">15.13.1 单样本模式 <a class="header-anchor" href="#_15-13-1-单样本模式" aria-label="Permalink to &quot;15.13.1 单样本模式&quot;">​</a></h4><p><code>TESTVAL</code> 子命令启用单样本模式。该模式用于将总体均值与假设均值进行检验。赋予 <code>TESTVAL</code> 子命令的值即为你想检验的对照值。在此模式下，你还必须使用 <code>/VARIABLES</code> 子命令告诉 PSPP 你想检验哪些变量。</p><h4 id="_15-13-1-1-示例-—-单样本-t-检验" tabindex="-1">15.13.1.1 示例 — 单样本 T 检验 <a class="header-anchor" href="#_15-13-1-1-示例-—-单样本-t-检验" aria-label="Permalink to &quot;15.13.1.1 示例 — 单样本 T 检验&quot;">​</a></h4><p>一位研究人员想知道某总体中人群的体重是否与全国平均值不同。样本从该总体中抽取，并记录在文件 physiology.sav 中。根据卫生部门的数据，她得知健康成年人的全国平均体重为 76.8kg。因此 <code>TESTVAL</code> 设为 76.8。于是原假设为：所抽取样本来源的总体的平均体重为 76.8kg。</p><p>如前所述（参见 <a href="./Identifying-incorrect-data">Identifying incorrect data</a>），数据集中有一个样本的体重值明显不正确。因此使用 <code>SELECT</code> 命令将其从分析中排除。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  select if (weight &gt; 0).  t-test testval = 76.8 	/variables = weight.</span></span></code></pre></div><p><strong>示例 15.6：</strong> 排除所有非正值后运行单样本 T 检验</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>图 15.5：</strong> 使用单样本 T 检验对话框检验 <strong>weight</strong> 的均值是否为 76.8kg</p><p>结果 15.2 显示，我们样本的平均值与检验值相差 -1.40kg。但显著性非常高（0.610）。因此无法拒绝原假设，必须得出：没有足够证据表明我们总体中人群的平均体重与 76.8kg 不同。</p><table tabindex="0"><thead><tr><th></th><th>t</th><th>df</th><th>显著性（双尾）</th><th>均值差</th><th>差值 95% 置信区间</th><th></th></tr></thead><tbody><tr><td></td><td>N</td><td>均值</td><td>标准差</td><td>均值标准误</td><td></td><td></td></tr><tr><td>体重（千克）</td><td>39</td><td>75.40</td><td>17.08</td><td>2.73</td><td></td><td></td></tr><tr><td></td><td>检验值 = 76.8</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>下限</td><td>上限</td><td></td><td></td><td></td><td></td></tr><tr><td>体重（千克）</td><td>-.51</td><td>38</td><td>.610</td><td>-1.40</td><td>-6.94</td><td>4.13</td></tr></tbody></table><p><strong>结果 15.2：</strong> 使用检验值 76.8kg 对 <strong>weight</strong> 进行单样本 T 检验的结果</p>',12)])])}const _=d(o,[["render",n]]);export{g as __pageData,_ as default};
